// 0xe82719202e5965Cf5D9B6673B7503a3b92DE20be#code
pragma solidity ^0.4.15;

contract PyramidVault {

        //Declare variables for storage critical to contract
        uint private vault = 0;
        uint private fees = 0;
        uint private feeBps = 10;
        uint private multiplier = 300;
        uint private payoutIndex = 0;

        address private admin;

        //Sets admin
        function Bootstrap() {
                admin = msg.sender;
        }

        modifier onlyowner {
                if (msg.sender == admin) _;
        }

        struct Participant {
                address wallet;
                uint reward;
        }

        Participant[] private entrants;

        //Fallback function
        function() {
                boot();
        }

        //boot function run on fallback
        function boot() private {
                //Ensures only tx with value of 1 ether or greater are processed and added to pyramid
                if (msg.value < 1 ether) {
                        fees += msg.value;
                        return;
                }

                uint _fee = feeBps;
                //50% fee rebate on any ether value of 50 or greater
                if (msg.value >= 50 ether) _fee /= 2;

                addEntry(_fee);
        }

        //Function called for valid tx to the contract
        function addEntry(uint _fee) private {
                //Adds new address to participant array
                entrants.push(Participant(msg.sender, (msg.value * multiplier) / 100));

                //These statements ensure a quicker reward system to later pyramid entrants, so the pyramid has a longer lifespan
                if (entrants.length == 10) multiplier = 200;
                else if (entrants.length == 25) multiplier = 150;

                // collect fees and update contract vault
                vault += (msg.value * (100 - _fee)) / 100;
                fees += (msg.value * _fee) / 100;

                //Pays earlier participiants if vault sufficient
                while (vault > entrants[payoutIndex].reward) {
                        uint payoutToSend = entrants[payoutIndex].reward;
                        entrants[payoutIndex].wallet.send(payoutToSend);

                        vault -= entrants[payoutIndex].reward;
                        payoutIndex += 1;
                }
        }

        //Fee functions for admin
        function sweep() onlyowner {
                if (fees == 0) throw;

                admin.send(fees);
                fees = 0;
        }

        function sweepPartial(uint _amt) onlyowner {
                _amt *= 1 ether;
                if (_amt > fees) sweep();

                if (fees == 0) throw;

                admin.send(_amt);
                fees -= _amt;
        }

        function sweepPercent(uint _pcent) onlyowner {
                if (fees == 0 || _pcent > 100) throw;

                uint feesToCollect = fees / 100 * _pcent;
                admin.send(feesToCollect);
                fees -= feesToCollect;
        }

        //Functions for changing variables related to the contract
        function setAdmin(address _owner) onlyowner {
                admin = _owner;
        }

        function setMultiplier(uint _mult) onlyowner {
                if (_mult > 300 || _mult < 120) throw;

                multiplier = _mult;
        }

        function setFeePercent(uint _fee) onlyowner {
                if (_fee > 10) throw;

                feeBps = _fee;
        }

        //Functions to provide information to end-user using JSON interface or other interfaces
        function getMultiplier() constant returns(uint multiplier, string info) {
                multiplier = multiplier;
                info = 'This multiplier applies to you as soon as transaction is received, may be lowered to hasten payouts or increased if payouts are fast enough. Due to no float or decimals, multiplier is x100 for a fractional multiplier e.g. 250 is actually a 2.5x multiplier. Capped at 3x max and 1.2x min.';
        }

        function getFeePercent() constant returns(uint fee, string info) {
                fee = feeBps;
                info = 'Shown in % form. Fee is halved(50%) for amounts equal or greater than 50 ethers. (Fee may change, but is capped to a maximum of 10%)';
        }

        function getVaultBalance() constant returns(uint pyramidBalance, string info) {
                pyramidBalance = vault / 1 ether;
                info = 'All vault values are measured in Ethers, note that due to no decimal placing, these values show up as integers only, within the contract itself you will get the exact decimal value you are supposed to';
        }

        function getNextPayout() constant returns(uint balancePayout) {
                balancePayout = entrants[payoutIndex].reward / 1 ether;
        }

        function getFees() constant returns(uint fees) {
                fees = fees / 1 ether;
        }

        function getParticipantCount() constant returns(uint count) {
                count = entrants.length;
        }

        function getPendingCount() constant returns(uint count) {
                count = entrants.length - payoutIndex;
        }

        function getParticipant(uint orderInPyramid) constant returns(address Address, uint Payout) {
                if (orderInPyramid <= entrants.length) {
                        Address = entrants[orderInPyramid].wallet;
                        Payout = entrants[orderInPyramid].reward / 1 ether;
                }
        }
}
